# 11-kimya-15 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Tümevarım: Hangi Oran Her Deneyde Sabit Kalıyor?</text><text x="380" y="48" text-anchor="middle" font-size="11" fill="#475569">H₂(g) + I₂(g) ⇌ 2HI(g) — aynı sıcaklık, farklı başlangıç miktarları, 1 L kap</text><rect x="30" y="60" width="700" height="32" rx="6" fill="#dbeafe" stroke="#2563eb"/><text x="75" y="81" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Deney</text><text x="160" y="81" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">[H₂]</text><text x="240" y="81" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">[I₂]</text><text x="320" y="81" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">[HI]</text><text x="470" y="81" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">Hipotez 1: [HI]/([H₂]·[I₂])</text><text x="640" y="81" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Hipotez 2: [HI]²/([H₂]·[I₂])</text><rect x="30" y="96" width="700" height="28" rx="5" fill="#ffffff" stroke="#cbd5e1"/><text x="75" y="115" text-anchor="middle" font-size="12" fill="#0f172a">1</text><text x="160" y="115" text-anchor="middle" font-size="12" fill="#0f172a">0,50</text><text x="240" y="115" text-anchor="middle" font-size="12" fill="#0f172a">0,50</text><text x="320" y="115" text-anchor="middle" font-size="12" fill="#0f172a">4,0</text><text x="470" y="115" text-anchor="middle" font-size="12" fill="#0f172a">16</text><text x="640" y="115" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">64</text><rect x="30" y="128" width="700" height="28" rx="5" fill="#f1f5f9" stroke="#cbd5e1"/><text x="75" y="147" text-anchor="middle" font-size="12" fill="#0f172a">2</text><text x="160" y="147" text-anchor="middle" font-size="12" fill="#0f172a">1,00</text><text x="240" y="147" text-anchor="middle" font-size="12" fill="#0f172a">0,25</text><text x="320" y="147" text-anchor="middle" font-size="12" fill="#0f172a">4,0</text><text x="470" y="147" text-anchor="middle" font-size="12" fill="#0f172a">16</text><text x="640" y="147" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">64</text><rect x="30" y="160" width="700" height="28" rx="5" fill="#ffffff" stroke="#cbd5e1"/><text x="75" y="179" text-anchor="middle" font-size="12" fill="#0f172a">3</text><text x="160" y="179" text-anchor="middle" font-size="12" fill="#0f172a">0,20</text><text x="240" y="179" text-anchor="middle" font-size="12" fill="#0f172a">0,80</text><text x="320" y="179" text-anchor="middle" font-size="12" fill="#0f172a">3,2</text><text x="470" y="179" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">20  (uymadı!)</text><text x="640" y="179" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">64</text><rect x="30" y="192" width="700" height="28" rx="5" fill="#f1f5f9" stroke="#cbd5e1"/><text x="75" y="211" text-anchor="middle" font-size="12" fill="#0f172a">4</text><text x="160" y="211" text-anchor="middle" font-size="12" fill="#0f172a">0,10</text><text x="240" y="211" text-anchor="middle" font-size="12" fill="#0f172a">0,10</text><text x="320" y="211" text-anchor="middle" font-size="12" fill="#0f172a">0,80</text><text x="470" y="211" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">80  (uymadı!)</text><text x="640" y="211" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">64</text><rect x="30" y="232" width="700" height="54" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="380" y="255" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">Sonuç: [HI]² / ([H₂]·[I₂]) = 64 her deneyde sabit</text><text x="380" y="275" text-anchor="middle" font-size="11.5" fill="#166534">Genelleme: derişimlerin üsleri = denkleştirilmiş tepkimedeki katsayılar</text></svg>', 'b2': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">N₂O₄(g) ⇌ 2NO₂(g) Derişim-Zaman Grafiği (1 L kap)</text><text x="78" y="52" font-size="11" fill="#334155">Derişim (M)</text><line x1="70" y1="58" x2="70" y2="250" stroke="#334155" stroke-width="2"/><line x1="70" y1="250" x2="480" y2="250" stroke="#334155" stroke-width="2"/><text x="62" y="74" text-anchor="end" font-size="11" fill="#334155">1,0</text><text x="62" y="110" text-anchor="end" font-size="11" fill="#334155">0,8</text><text x="62" y="182" text-anchor="end" font-size="11" fill="#334155">0,4</text><text x="62" y="254" text-anchor="end" font-size="11" fill="#334155">0</text><line x1="70" y1="106" x2="480" y2="106" stroke="#cbd5e1" stroke-dasharray="3,3"/><line x1="70" y1="178" x2="480" y2="178" stroke="#cbd5e1" stroke-dasharray="3,3"/><path d="M70,70 Q150,100 230,106 L470,106" fill="none" stroke="#2563eb" stroke-width="3"/><path d="M70,250 Q150,190 230,178 L470,178" fill="none" stroke="#b45309" stroke-width="3"/><line x1="230" y1="60" x2="230" y2="250" stroke="#64748b" stroke-width="1.5" stroke-dasharray="6,4"/><text x="230" y="266" text-anchor="middle" font-size="11" font-weight="bold" fill="#475569">denge anı</text><text x="470" y="268" text-anchor="end" font-size="11" fill="#334155">Zaman</text><text x="350" y="98" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">N₂O₄ (renksiz)</text><text x="350" y="170" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">NO₂ (kahverengi)</text><rect x="500" y="50" width="240" height="230" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="620" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Grafikten Çıkarımlar</text><text x="512" y="100" font-size="11.5" fill="#78350f">• N₂O₄: 1,0 → 0,8 (azalma 0,2)</text><text x="512" y="122" font-size="11.5" fill="#78350f">• NO₂: 0 → 0,4 (artma 0,4)</text><text x="512" y="144" font-size="11.5" fill="#78350f">• Oran 0,2 : 0,4 = 1 : 2</text><text x="512" y="166" font-size="11.5" fill="#78350f">• Denge sonrası eğriler yatay</text><text x="512" y="188" font-size="11.5" font-weight="bold" fill="#b91c1c">• Derişimler EŞİT değil, SABİT</text><text x="512" y="210" font-size="11.5" fill="#78350f">• Renk sabitlenir, tepkime sürer</text><rect x="516" y="226" width="208" height="40" rx="8" fill="#ffffff" stroke="#d97706"/><text x="620" y="251" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Kc = (0,4)² / 0,8 = 0,2</text></svg>', 'b3': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Denge Sabitinin Büyüklüğü ve Tepkimenin Kapsamı</text><text x="380" y="50" text-anchor="middle" font-size="11" fill="#475569">K değeri ölçeği (her aralık 10\'un kuvvetleriyle büyür)</text><rect x="40" y="70" width="250" height="44" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><rect x="290" y="70" width="180" height="44" rx="0" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><rect x="470" y="70" width="250" height="44" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="165" y="97" text-anchor="middle" font-size="14" font-weight="bold" fill="#991b1b">K &lt; 10⁻³</text><text x="380" y="97" text-anchor="middle" font-size="14" font-weight="bold" fill="#92400e">10⁻³ – 10³</text><text x="595" y="97" text-anchor="middle" font-size="14" font-weight="bold" fill="#166534">K &gt; 10³</text><text x="40" y="132" text-anchor="middle" font-size="11" fill="#334155">10⁻¹⁰</text><text x="290" y="132" text-anchor="middle" font-size="11" fill="#334155">10⁻³</text><text x="380" y="132" text-anchor="middle" font-size="11" fill="#334155">1</text><text x="470" y="132" text-anchor="middle" font-size="11" fill="#334155">10³</text><text x="720" y="132" text-anchor="middle" font-size="11" fill="#334155">10¹⁰</text><rect x="40" y="146" width="220" height="86" rx="10" fill="#ffffff" stroke="#dc2626"/><text x="150" y="168" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Girenler baskın</text><text x="150" y="190" text-anchor="middle" font-size="11" fill="#7f1d1d">Çok az ürün oluşur</text><text x="150" y="210" text-anchor="middle" font-size="11" fill="#7f1d1d">Örnek: N₂ + O₂ ⇌ 2NO (25 °C)</text><rect x="270" y="146" width="220" height="86" rx="10" fill="#ffffff" stroke="#d97706"/><text x="380" y="168" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">Karşılaştırılabilir</text><text x="380" y="190" text-anchor="middle" font-size="11" fill="#78350f">Giren ve ürün birlikte</text><text x="380" y="210" text-anchor="middle" font-size="11" fill="#78350f">Örnek: N₂O₄ ⇌ 2NO₂ (Kc = 0,2)</text><rect x="500" y="146" width="220" height="86" rx="10" fill="#ffffff" stroke="#16a34a"/><text x="610" y="168" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Ürünler baskın</text><text x="610" y="190" text-anchor="middle" font-size="11" fill="#14532d">Tepkime neredeyse tamamlanır</text><text x="610" y="210" text-anchor="middle" font-size="11" fill="#14532d">Girenler eser miktarda kalır</text><rect x="40" y="244" width="680" height="40" rx="10" fill="#e0e7ff" stroke="#4f46e5"/><text x="380" y="269" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">Uyarı: K tepkimenin NE KADAR ilerlediğini söyler, NE KADAR HIZLI olduğunu söylemez.</text></svg>', 'b4': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Fiziksel Değişimlerde Denge ve Denge Sabiti İfadeleri</text><rect x="20" y="48" width="230" height="196" rx="12" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/><text x="135" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">BUHARLAŞMA</text><rect x="95" y="84" width="80" height="70" rx="6" fill="#ffffff" stroke="#1e3a8a"/><rect x="96" y="126" width="78" height="27" rx="4" fill="#93c5fd"/><circle cx="115" cy="100" r="3" fill="#2563eb"/><circle cx="140" cy="108" r="3" fill="#2563eb"/><circle cx="158" cy="96" r="3" fill="#2563eb"/><text x="135" y="176" text-anchor="middle" font-size="12" fill="#1e3a8a">H₂O(s) ⇌ H₂O(g)</text><text x="135" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Kc = [H₂O(g)]</text><text x="135" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">Kp = P(H₂O)</text><text x="135" y="238" text-anchor="middle" font-size="10" fill="#1e40af">= buhar basıncı</text><rect x="265" y="48" width="230" height="196" rx="12" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/><text x="380" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">SÜBLİMLEŞME</text><rect x="340" y="84" width="80" height="70" rx="6" fill="#ffffff" stroke="#6b21a8"/><rect x="350" y="136" width="22" height="16" rx="2" fill="#581c87"/><rect x="378" y="140" width="18" height="12" rx="2" fill="#581c87"/><circle cx="360" cy="100" r="3" fill="#a855f7"/><circle cx="385" cy="112" r="3" fill="#a855f7"/><circle cx="405" cy="98" r="3" fill="#a855f7"/><text x="380" y="176" text-anchor="middle" font-size="12" fill="#6b21a8">I₂(k) ⇌ I₂(g)</text><text x="380" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Kc = [I₂(g)]</text><text x="380" y="220" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Kp = P(I₂)</text><text x="380" y="238" text-anchor="middle" font-size="10" fill="#7e22ce">katı miktarından bağımsız</text><rect x="510" y="48" width="230" height="196" rx="12" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="625" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ÇÖZÜNME</text><rect x="585" y="84" width="80" height="70" rx="6" fill="#ffffff" stroke="#166534"/><rect x="586" y="100" width="78" height="53" rx="4" fill="#bbf7d0"/><rect x="600" y="142" width="50" height="10" rx="2" fill="#f1f5f9" stroke="#64748b"/><text x="625" y="176" text-anchor="middle" font-size="11.5" fill="#166534">AgCl(k) ⇌ Ag⁺ + Cl⁻</text><text x="625" y="198" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">Kc = [Ag⁺]·[Cl⁻]</text><text x="625" y="220" text-anchor="middle" font-size="11" fill="#166534">Şeker için Kc = [şeker]</text><text x="625" y="238" text-anchor="middle" font-size="10" fill="#15803d">= doygun çözelti derişimi</text><rect x="20" y="254" width="720" height="36" rx="10" fill="#fef3c7" stroke="#d97706"/><text x="380" y="277" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Ortak örüntü: (k) ve (s) yazılmaz; buhar basıncı ve çözünürlük de yalnız sıcaklıkla değişir.</text></svg>', 'b5': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Denge İfadesi Modelleme Akışı (Faz Filtresi)</text><rect x="20" y="50" width="160" height="84" rx="12" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/><text x="100" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">1. Net İyon</text><text x="100" y="96" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e3a8a">Denklemi</text><text x="100" y="118" text-anchor="middle" font-size="10.5" fill="#1e40af">seyirci iyonları at</text><polygon points="186,86 204,92 186,98" fill="#64748b"/><line x1="180" y1="92" x2="190" y2="92" stroke="#64748b" stroke-width="2"/><rect x="208" y="50" width="160" height="84" rx="12" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/><text x="288" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">2. Faz Filtresi</text><text x="288" y="98" text-anchor="middle" font-size="11" fill="#7f1d1d">(k) ve (s) ELENİR</text><text x="288" y="118" text-anchor="middle" font-size="11" fill="#7f1d1d">(g) ve (suda) KALIR</text><polygon points="374,86 392,92 374,98" fill="#64748b"/><line x1="368" y1="92" x2="378" y2="92" stroke="#64748b" stroke-width="2"/><rect x="396" y="50" width="160" height="84" rx="12" fill="#fef3c7" stroke="#d97706" stroke-width="2"/><text x="476" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#92400e">3. Kesri Kur</text><text x="476" y="98" text-anchor="middle" font-size="11" fill="#78350f">ürünler → pay</text><text x="476" y="118" text-anchor="middle" font-size="11" fill="#78350f">girenler → payda</text><polygon points="562,86 580,92 562,98" fill="#64748b"/><line x1="556" y1="92" x2="566" y2="92" stroke="#64748b" stroke-width="2"/><rect x="584" y="50" width="156" height="84" rx="12" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="662" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">4. Üsleri Ekle</text><text x="662" y="98" text-anchor="middle" font-size="11" fill="#14532d">üs = katsayı</text><text x="662" y="118" text-anchor="middle" font-size="11" fill="#14532d">boş tarafa 1 yaz</text><rect x="20" y="152" width="720" height="132" rx="12" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/><text x="380" y="176" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">Uygulama: Pb(NO₃)₂(suda) + 2KI(suda) ⇌ PbI₂(k) + 2KNO₃(suda)</text><text x="380" y="200" text-anchor="middle" font-size="12" fill="#475569">Seyirci iyonlar K⁺ ve NO₃⁻ çıkarılır  →  Net: Pb²⁺(suda) + 2I⁻(suda) ⇌ PbI₂(k)</text><text x="380" y="224" text-anchor="middle" font-size="12" fill="#991b1b">PbI₂(k) katı olduğu için elenir → payda hiçbir tür kalmaz → paya 1 yazılır</text><rect x="240" y="238" width="280" height="36" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="380" y="262" text-anchor="middle" font-size="14" font-weight="bold" fill="#14532d">Kc = 1 / ([Pb²⁺]·[I⁻]²)</text></svg>', 'b6': '<svg viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif"><rect x="0" y="0" width="760" height="300" rx="14" fill="#f8fafc"/><text x="380" y="28" text-anchor="middle" font-size="16" font-weight="bold" fill="#0f172a">Ters Modelleme: İfadeden Denkleme, Denklemden Birime</text><rect x="20" y="48" width="300" height="100" rx="12" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/><text x="170" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#3730a3">Verilen Denge İfadesi</text><text x="170" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#312e81">[NO]⁴·[H₂O]⁶</text><line x1="90" y1="108" x2="250" y2="108" stroke="#312e81" stroke-width="1.5"/><text x="170" y="128" text-anchor="middle" font-size="13" font-weight="bold" fill="#312e81">[NH₃]⁴·[O₂]⁵</text><text x="60" y="114" text-anchor="middle" font-size="13" font-weight="bold" fill="#312e81">Kc =</text><line x1="325" y1="98" x2="405" y2="98" stroke="#64748b" stroke-width="2.5"/><polygon points="405,90 422,98 405,106" fill="#64748b"/><text x="372" y="88" text-anchor="middle" font-size="10.5" fill="#475569">pay = ürün</text><text x="372" y="120" text-anchor="middle" font-size="10.5" fill="#475569">üs = katsayı</text><rect x="428" y="48" width="312" height="100" rx="12" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/><text x="584" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Kurulan Denklem</text><text x="584" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">4NH₃(g) + 5O₂(g) ⇌ 4NO(g) + 6H₂O(g)</text><text x="584" y="126" text-anchor="middle" font-size="10.5" fill="#15803d">Kontrol: 4 N, 12 H, 10 O her iki tarafta</text><rect x="20" y="162" width="720" height="124" rx="12" fill="#ffffff" stroke="#94a3b8" stroke-width="1.5"/><text x="380" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#0f172a">Kc Birimi = (mol/L) üzeri Δ     Δ = pay üsleri toplamı − payda üsleri toplamı</text><rect x="40" y="198" width="160" height="74" rx="10" fill="#f1f5f9" stroke="#64748b"/><text x="120" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#334155">Δ = 0</text><text x="120" y="244" text-anchor="middle" font-size="11" fill="#334155">Birimsiz</text><text x="120" y="262" text-anchor="middle" font-size="10" fill="#64748b">H₂ + I₂ ⇌ 2HI</text><rect x="215" y="198" width="160" height="74" rx="10" fill="#fef3c7" stroke="#d97706"/><text x="295" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">Δ = +1</text><text x="295" y="244" text-anchor="middle" font-size="11" fill="#92400e">mol/L</text><text x="295" y="262" text-anchor="middle" font-size="10" fill="#b45309">PCl₅ ⇌ PCl₃ + Cl₂</text><rect x="390" y="198" width="160" height="74" rx="10" fill="#fee2e2" stroke="#dc2626"/><text x="470" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">Δ = −2</text><text x="470" y="244" text-anchor="middle" font-size="11" fill="#991b1b">L²/mol²</text><text x="470" y="262" text-anchor="middle" font-size="10" fill="#b91c1c">N₂ + 3H₂ ⇌ 2NH₃</text><rect x="565" y="198" width="160" height="74" rx="10" fill="#f3e8ff" stroke="#9333ea"/><text x="645" y="222" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Δ = −3</text><text x="645" y="244" text-anchor="middle" font-size="11" fill="#6b21a8">L³/mol³</text><text x="645" y="262" text-anchor="middle" font-size="10" fill="#7e22ce">Pb²⁺ + 2I⁻ ⇌ PbI₂(k)</text></svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
